import Cocoa
import Quartz
import WebKit



enum EmbeddedFont {
    /// Cal Sans Regular (OFL). Compiled in so the QuickLook extension
    /// has zero filesystem dependency at preview time — extensions
    /// run sandboxed and can't read arbitrary bundle paths reliably.
    static let calSansBase64: String = ""

    /// Static inline blob mark (icon-inline-dark.svg from
    /// assets/brand/mwlogoset v2). Used as a CSS mask so the
    /// wordmark blob tints with the current theme color.
    static let blobBase64: String = ""
}

enum EmbeddedRender {
    /// @mdcore/editor UMD bundle — same renderer apps/web ships.
    /// Generated by `cd packages/editor && npm run build`. ~2.5 MB raw,
    /// ~3.5 MB base64. Inlined here so the QuickLook .appex works in
    /// the macOS app extension sandbox without filesystem reads.
    static let renderUMD: String = ""

    /// KaTeX CSS — required to style server-rendered math widgets.
    /// ~32 KB base64.
    static let katexCSS: String = ""

    /// highlight.js github-dark theme — paints the .hljs-* spans the
    /// renderer emits inside code blocks.
    static let hljsCSS: String = ""
}


class PreviewViewController: NSViewController, QLPreviewingController, WKNavigationDelegate {

    var webView: WKWebView!

    override func loadView() {
        let config = WKWebViewConfiguration()
        config.preferences.setValue(true, forKey: "allowFileAccessFromFileURLs")
        webView = WKWebView(frame: NSRect(x: 0, y: 0, width: 800, height: 600), configuration: config)
        webView.autoresizingMask = [.width, .height]
        // QL extensions run sandboxed — anchor clicks with target=_blank
        // silently no-op unless we intercept them and hand the URL off
        // to NSWorkspace. The user-visible "Open in memory.wiki" link
        // in the topbar depends on this.
        webView.navigationDelegate = self
        self.view = webView
    }

    func webView(_ webView: WKWebView, decidePolicyFor navigationAction: WKNavigationAction, decisionHandler: @escaping (WKNavigationActionPolicy) -> Void) {
        // First navigation (the loadHTMLString itself) is .other and
        // has no URL or about:blank — allow it. Real anchor clicks
        // surface as .linkActivated and we route those out to the
        // user's default browser.
        if navigationAction.navigationType == .linkActivated,
           let url = navigationAction.request.url,
           url.scheme == "http" || url.scheme == "https" {
            NSWorkspace.shared.open(url)
            decisionHandler(.cancel)
            return
        }
        decisionHandler(.allow)
    }

    func preparePreviewOfFile(at url: URL, completionHandler handler: @escaping (Error?) -> Void) {
        do {
            let attributes = try FileManager.default.attributesOfItem(atPath: url.path)
            let fileSize = attributes[.size] as? Int64 ?? 0
            let maxSize: Int64 = 10_000_000 // 10MB

            var markdown: String
            if fileSize > maxSize {
                let truncatedData = try Data(contentsOf: url).prefix(Int(maxSize))
                markdown = (String(data: truncatedData, encoding: .utf8) ?? "") + "\n\n---\n\n> **Note:** This file was truncated for preview (original size: \(fileSize / 1_000_000)MB). Open in memory.wiki for the full document."
            } else {
                markdown = try String(contentsOf: url, encoding: .utf8)
            }
            let fileName = url.lastPathComponent
            let html = generateHTML(markdown: markdown, fileName: fileName)

            DispatchQueue.main.async {
                self.webView.loadHTMLString(html, baseURL: nil)
            }

            handler(nil)
        } catch {
            handler(error)
        }
    }

    // MARK: - HTML Generation

    private func generateHTML(markdown: String, fileName: String) -> String {
        let escaped = escapeForJS(markdown)
        let css = Self.previewCSS
        let template = Self.htmlTemplate
            .replacingOccurrences(of: "{{MDFY_CSS}}", with: css)
            .replacingOccurrences(of: "{{MARKDOWN_CONTENT}}", with: escaped)
            .replacingOccurrences(of: "{{FILE_NAME}}", with: escapeHTML(fileName))

        return template
    }

    private func escapeForJS(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "\\", with: "\\\\")
            .replacingOccurrences(of: "`", with: "\\`")
            .replacingOccurrences(of: "$", with: "\\$")
            .replacingOccurrences(of: "\r\n", with: "\n")
    }

    private func escapeHTML(_ string: String) -> String {
        return string
            .replacingOccurrences(of: "&", with: "&amp;")
            .replacingOccurrences(of: "<", with: "&lt;")
            .replacingOccurrences(of: ">", with: "&gt;")
            .replacingOccurrences(of: "\"", with: "&quot;")
    }

    // MARK: - Embedded Assets

    /// Full inline CSS -- no CDN dependency for styles
    static let previewCSS: String = """
    /* ── Base ── */
    .mdcore-rendered {
      color: var(--text-secondary);
