      mask: url('data:image/svg+xml;base64,\(EmbeddedFont.blobBase64)') center / contain no-repeat;
    }

    /* Dark — v8 ink tokens (sync with apps/desktop/renderer/_tokens.dark.generated) */
    :root {
      --background: #15151a;
      --foreground: #fafafa;
      --accent: #fafafa;
      --accent-dim: rgba(255, 255, 255, 0.08);
      --surface: #18181b;
