        --background: #faf9f7;
        --foreground: #09090b;
        --accent: #09090b;
        --accent-dim: rgba(0, 0, 0, 0.06);
        --surface: #f4f4f5;
        --surface-hover: rgba(0, 0, 0, 0.04);
        --border: #e4e4e7;
        --border-dim: rgba(228, 228, 231, 0.6);
        --text-primary: #09090b;
        --text-secondary: #3f3f46;
        --text-tertiary: #71717a;
        --text-muted: #71717a;
        --text-faint: #a1a1aa;
        --math-color: #7c3aed;
