        --h2-color: #27272a;
        --scrollbar-thumb: #a1a1aa;
        --scrollbar-hover: #a1a1aa;
        --fg: #09090b;
        --muted: #a1a1aa;
      }
    }

    * { margin: 0; padding: 0; box-sizing: border-box; }
    html, body {
      height: 100%;
      background: var(--background);
      color: var(--foreground);
      font-family: var(--font-sans);
