    }
    @media (prefers-color-scheme: light) {
      .mermaid-container {
        background: linear-gradient(145deg, #f8f9fa, #ffffff);
        border-color: #e2e8f0;
        box-shadow: 0 2px 8px rgba(0, 0, 0, 0.06);
      }
    }
    .mermaid-container svg { max-width: 100%; height: auto; }

    /* Light mode hljs overrides */
    @media (prefers-color-scheme: light) {
