    <!-- CDN JS libraries, loaded with fallback handling -->
    <script>
    // Track which libraries loaded successfully
    window.__mwLibs = { marked: false, hljs: false, katex: false, mermaid: false };

    // Theme toggle
    var isDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
    function updateThemeIcons() {
      document.getElementById('theme-icon-sun').style.display = isDark ? 'none' : 'block';
      document.getElementById('theme-icon-moon').style.display = isDark ? 'block' : 'none';
    }
    function toggleTheme() {
      isDark = !isDark;
      if (isDark) {
        document.documentElement.style.colorScheme = 'dark';
        document.documentElement.removeAttribute('data-theme');
      } else {
        document.documentElement.style.colorScheme = 'light';
        document.documentElement.setAttribute('data-theme', 'light');
      }
      // Override CSS variables manually since prefers-color-scheme won't change
      var root = document.documentElement.style;
      if (isDark) {
        root.setProperty('--background', '#15151a');
        root.setProperty('--foreground', '#fafafa');
        root.setProperty('--accent', '#fafafa');
        root.setProperty('--surface', '#18181b');
        root.setProperty('--border', '#27272a');
        root.setProperty('--border-dim', 'rgba(39,39,42,0.6)');
        root.setProperty('--text-primary', '#fafafa');
        root.setProperty('--text-secondary', '#d4d4d8');
        root.setProperty('--text-muted', '#a1a1aa');
        root.setProperty('--text-faint', '#8a8a91');
        root.setProperty('--fg', '#fafafa');
        root.setProperty('--muted', '#8a8a91');
        root.setProperty('--accent-dim', 'rgba(255, 255, 255, 0.08)');
        root.setProperty('--surface-hover', 'rgba(255, 255, 255, 0.03)');
        root.setProperty('--text-tertiary', '#a1a1aa');
        root.setProperty('--math-color', '#c4b5fd');
        root.setProperty('--math-display-color', '#ddd6fe');
        root.setProperty('--h2-color', '#e4e4e7');
        root.setProperty('--scrollbar-thumb', '#27272a');
        root.setProperty('--scrollbar-hover', '#3f3f46');
      } else {
        root.setProperty('--background', '#faf9f7');
        root.setProperty('--foreground', '#18181b');
        root.setProperty('--accent', '#09090b');
        root.setProperty('--surface', '#f4f4f5');
        root.setProperty('--border', '#e4e4e7');
        root.setProperty('--border-dim', 'rgba(228,228,231,0.6)');
        root.setProperty('--text-primary', '#09090b');
        root.setProperty('--text-secondary', '#3f3f46');
        root.setProperty('--text-muted', '#a1a1aa');
        root.setProperty('--text-faint', '#a1a1aa');
        root.setProperty('--fg', '#18181b');
        root.setProperty('--muted', '#a1a1aa');
        root.setProperty('--accent-dim', 'rgba(0, 0, 0, 0.06)');
        root.setProperty('--surface-hover', 'rgba(0, 0, 0, 0.04)');
        root.setProperty('--text-tertiary', '#71717a');
        root.setProperty('--math-color', '#7c3aed');
        root.setProperty('--math-display-color', '#6d28d9');
        root.setProperty('--h2-color', '#27272a');
        root.setProperty('--scrollbar-thumb', '#a1a1aa');
        root.setProperty('--scrollbar-hover', '#a1a1aa');
      }
      document.body.style.background = isDark ? '#15151a' : '#faf9f7';
      updateThemeIcons();
    }
    updateThemeIcons();
    </script>

    <!-- Inlined @mdcore/editor UMD (markdown-it + katex + hljs +
         postprocessing). Same renderer the web viewer + Desktop +
         VSCode + iOS + Android channels use, so the QuickLook
         output is byte-identical to opening the doc in the web. -->
    <script src="data:text/javascript;base64,\(EmbeddedRender.renderUMD)"></script>

    <script>
    (function() {
      'use strict';

      const markdownContent = `{{MARKDOWN_CONTENT}}`;
      const previewEl = document.getElementById('preview');

      function paint() {
        try {
          const out = (window.MemoryWikiRender || {}).render
            ? window.MemoryWikiRender.render(markdownContent)
            : { html: '<pre>' + markdownContent.replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])) + '</pre>' };
          previewEl.innerHTML = out.html;
        } catch (err) {
          console.error('[QuickLook] render failed:', err);
          previewEl.innerHTML = '<pre class="mw-raw-fallback">' +
            markdownContent.replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])) +
            '</pre>';
        }

        // Mermaid: render any <pre><code class="language-mermaid">
        // blocks the @mdcore/editor renderer left as plain text.
        // Mermaid.js itself is intentionally NOT inlined (~2 MB
        // would bloat the .appex) — load via CDN, falls back to
        // the rendered code source if offline.
        if (previewEl.querySelector('code.language-mermaid')) {
          loadMermaid().then((mermaid) => {
            previewEl.querySelectorAll('code.language-mermaid').forEach((codeEl, i) => {
              const id = 'mw-mermaid-' + i;
              const wrap = document.createElement('div');
              wrap.className = 'mermaid-container';
              wrap.id = id;
              codeEl.closest('pre').replaceWith(wrap);
              try {
                mermaid.render(id + '-svg', codeEl.textContent).then(({ svg }) => {
                  wrap.innerHTML = svg;
                }).catch(() => {
                  wrap.innerHTML = '<pre><code>' + codeEl.textContent.replace(/[&<>]/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;' }[c])) + '</code></pre>';
                });
              } catch { /* keep as <code> source */ }
            });
          }).catch(() => { /* offline — leave mermaid as <code> */ });
        }
      }

      function loadMermaid() {
        if (window.mermaid) return Promise.resolve(window.mermaid);
        return new Promise((resolve, reject) => {
          const s = document.createElement('script');
          s.src = 'https://cdn.jsdelivr.net/npm/mermaid@11/dist/mermaid.min.js';
          s.onload = () => {
            try { window.mermaid.initialize({ startOnLoad: false, theme: isDark ? 'dark' : 'default' }); } catch {}
            resolve(window.mermaid);
          };
          s.onerror = reject;
          document.head.appendChild(s);
        });
      }

      paint();
    })();
    </script>
    </body>
    </html>
